PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS platforms(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified',last_success TEXT,last_error TEXT,failure_count INTEGER NOT NULL DEFAULT 0,circuit_until REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,title TEXT NOT NULL,brand TEXT,model TEXT,gtin TEXT,category TEXT DEFAULT 'Other',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),attributes TEXT NOT NULL,UNIQUE(product_id,attributes));
CREATE TABLE IF NOT EXISTS sellers(id TEXT PRIMARY KEY,platform_id TEXT NOT NULL REFERENCES platforms(id),name TEXT NOT NULL,UNIQUE(platform_id,name));
CREATE TABLE IF NOT EXISTS listings(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES variants(id),platform_id TEXT NOT NULL REFERENCES platforms(id),external_id TEXT NOT NULL,url TEXT NOT NULL,seller_id TEXT REFERENCES sellers(id),latest_price INTEGER,last_success TEXT,stale INTEGER NOT NULL DEFAULT 0,verification TEXT NOT NULL,availability TEXT NOT NULL,UNIQUE(platform_id,url));
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,listing_id TEXT NOT NULL REFERENCES listings(id),price INTEGER NOT NULL CHECK(price>0),mrp INTEGER,shipping INTEGER,observed_at TEXT NOT NULL,seller TEXT,availability TEXT NOT NULL,verification TEXT NOT NULL,evidence TEXT,UNIQUE(listing_id,observed_at));
CREATE INDEX IF NOT EXISTS observation_history ON observations(listing_id,verification,observed_at);
CREATE INDEX IF NOT EXISTS product_model ON products(brand,model);
CREATE INDEX IF NOT EXISTS product_gtin ON products(gtin);
CREATE TABLE IF NOT EXISTS discounts(id TEXT PRIMARY KEY,observation_id TEXT NOT NULL REFERENCES observations(id),kind TEXT NOT NULL,details TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,settings TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS watchlists(session_id TEXT NOT NULL REFERENCES sessions(id),listing_id TEXT NOT NULL REFERENCES listings(id),created_at TEXT NOT NULL,PRIMARY KEY(session_id,listing_id));
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),listing_id TEXT NOT NULL REFERENCES listings(id),target_price INTEGER NOT NULL CHECK(target_price>0),armed INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),alert_id TEXT REFERENCES alerts(id),message TEXT NOT NULL,created_at TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS monitoring_jobs(listing_id TEXT PRIMARY KEY REFERENCES listings(id),due_at REAL NOT NULL,interval_seconds INTEGER NOT NULL DEFAULT 21600 CHECK(interval_seconds>=900),attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',lease_until REAL NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_due ON monitoring_jobs(state,due_at);
CREATE TABLE IF NOT EXISTS collection_errors(id TEXT PRIMARY KEY,platform_id TEXT REFERENCES platforms(id),listing_id TEXT REFERENCES listings(id),code TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS matching_decisions(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),candidate_id TEXT REFERENCES products(id),decision TEXT NOT NULL,confidence REAL NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS watchlist_owner ON watchlists(session_id);
CREATE INDEX IF NOT EXISTS notification_owner ON notifications(session_id,created_at);
